import type { EntityItem, Fields, FieldValue } from './entity';

/*
 * The sync protocol. Sync has its own versioning, separate from the domain's: a user-wide
 * sequence number, bumped on every write and stamped on the row it wrote. A device remembers
 * the highest one it has seen (its cursor) and asks for everything after it.
 */

/** Item ids are ULIDs: 26 characters of Crockford base32, generated by the client. */
export const ID_PATTERN = /^[0-9A-HJKMNP-TV-Z]{26}$/;

/** Operation and device ids are chosen by clients; ULIDs fit. */
export const TOKEN_PATTERN = /^[A-Za-z0-9_-]{1,64}$/;

/** Entity and field names. */
export const NAME_PATTERN = /^[a-z][A-Za-z0-9_]{0,31}$/;

export const MAX_OPS_PER_PUSH = 100;
export const MAX_FIELDS_PER_OP = 32;
export const DEFAULT_PULL_LIMIT = 200;
export const MAX_PULL_LIMIT = 500;

export interface CreateOp {
  kind: 'create';
  opId: string;
  entity: string;
  itemId: string;
  fields: Fields;
}

export interface UpdateOp {
  kind: 'update';
  opId: string;
  entity: string;
  itemId: string;
  /** The domain revision the device last saw. Informational: fields merge whatever the base. */
  baseRev: number;
  /** The fields to write. Fields left out are untouched. */
  changes: Fields;
}

export interface DeleteOp {
  kind: 'delete';
  opId: string;
  entity: string;
  itemId: string;
}

/** One change from a device. Sending the same `opId` again has no further effect. */
export type SyncOp = CreateOp | UpdateOp | DeleteOp;

export type RejectReason =
  | 'invalid_op'
  | 'unknown_entity'
  | 'unknown_item'
  | 'invalid_field'
  | 'rule_violation'
  | 'limit_reached';

/** `duplicate` means the op was applied before. Either way the device learns the result by pulling. */
export type OpResult =
  | { opId: string; status: 'applied' | 'duplicate' }
  | { opId: string; status: 'rejected'; reason: RejectReason; message: string };

export interface PushRequest {
  deviceId: string;
  ops: SyncOp[];
}

/** `results[i]` answers `ops[i]`. */
export interface PushResponse {
  results: OpResult[];
}

/** A row a device should take on: the item as it is now, or null when it was deleted. */
export interface Change {
  seq: number;
  entity: string;
  id: string;
  item: EntityItem | null;
}

/**
 * Changes after the cursor, oldest first. `resync` means the server can no longer say what
 * changed since the cursor, because it has forgotten old deletions: the device must drop its
 * copy and pull again from zero. It must do the same when `epoch` is not the one it last saw,
 * which means the server's data started again from nothing.
 */
export type PullResponse =
  | { resync: false; epoch: number; changes: Change[]; latestSeq: number; hasMore: boolean }
  | { resync: true };

export type ParsedOp = { ok: true; op: SyncOp } | { ok: false; opId: string };

export type ParsedPush =
  { ok: true; deviceId: string; ops: ParsedOp[] } | { ok: false; message: string };

/**
 * Checks the shape of a push body. A malformed op does not fail the batch: it comes back as
 * `{ ok: false }` so the server can reject that op alone and keep the rest moving.
 */
export function parsePushRequest(body: unknown): ParsedPush {
  if (!isRecord(body)) return { ok: false, message: 'Body must be a JSON object.' };
  if (!isToken(body.deviceId)) return { ok: false, message: 'deviceId is missing or invalid.' };
  if (!Array.isArray(body.ops) || body.ops.length > MAX_OPS_PER_PUSH) {
    return { ok: false, message: `ops must be a list of at most ${MAX_OPS_PER_PUSH} operations.` };
  }
  return { ok: true, deviceId: body.deviceId, ops: body.ops.map(parseOp) };
}

/** Checks an op's shape only. What its fields mean is for the schemas to say. */
export function parseOp(raw: unknown): ParsedOp {
  const invalid: ParsedOp = { ok: false, opId: isRecord(raw) && isToken(raw.opId) ? raw.opId : '' };
  if (!isRecord(raw) || !isToken(raw.opId) || !isUlid(raw.itemId) || !isName(raw.entity)) {
    return invalid;
  }
  const { opId, entity, itemId } = raw;

  switch (raw.kind) {
    case 'create': {
      const fields = parseFields(raw.fields, true);
      return fields ? { ok: true, op: { kind: 'create', opId, entity, itemId, fields } } : invalid;
    }
    case 'update': {
      const { baseRev } = raw;
      if (typeof baseRev !== 'number' || !Number.isInteger(baseRev) || baseRev < 0) return invalid;
      const changes = parseFields(raw.changes, false);
      return changes
        ? { ok: true, op: { kind: 'update', opId, entity, itemId, baseRev, changes } }
        : invalid;
    }
    case 'delete':
      return { ok: true, op: { kind: 'delete', opId, entity, itemId } };
    default:
      return invalid;
  }
}

function parseFields(raw: unknown, mayBeEmpty: boolean): Fields | null {
  if (!isRecord(raw)) return null;
  const entries = Object.entries(raw);
  if (entries.length > MAX_FIELDS_PER_OP || (!mayBeEmpty && entries.length === 0)) return null;

  const fields: Fields = {};
  for (const [name, value] of entries) {
    if (!NAME_PATTERN.test(name) || !isFieldValue(value)) return null;
    fields[name] = value;
  }
  return fields;
}

function isFieldValue(value: unknown): value is FieldValue {
  return (
    value === null ||
    typeof value === 'string' ||
    typeof value === 'boolean' ||
    (typeof value === 'number' && Number.isFinite(value))
  );
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isToken(value: unknown): value is string {
  return typeof value === 'string' && TOKEN_PATTERN.test(value);
}

function isName(value: unknown): value is string {
  return typeof value === 'string' && NAME_PATTERN.test(value);
}

function isUlid(value: unknown): value is string {
  return typeof value === 'string' && ID_PATTERN.test(value);
}
